  ['legThick', '腿的粗细', 0.5, 1.7, 1.0], ['legGap', '两腿间距', 0.5, 1.8, 1], ['footSize', '脚的大小', 0.6, 1.7, 0.96], ['tailThick', '尾巴粗细', 0.4, 1.7, 0.92], ['shoulderW', '脖子下方宽度', 0.8, 1.6, 1.18], ['whiskY', '胡子高低', -0.15, 0.25, 0.04]
