  for (const side of ['L', 'R']) { const s = side === 'L' ? -1 : 1; SHOULDER[side].x = s * Math.min(0.25 * P.legGap, 0.42 * P.bodyW); SHOULDER[side].y = 1.5 * P.bodyH; REST[side].x = s * 0.23 * P.legGap; UP[side].x = s * 0.46 * P.legGap; UP[side].y = 1.1 * P.bodyH;
  }
