on('pointermove', e => { const r = stageEl.getBoundingClientRect(); const nx = (e.clientX - r.left) / r.width * 2 - 1, ny = (e.clientY - r.top) / r.height * 2 - 1; S.gaze = { x: nx, y: ny }; S.pointer = { x: -nx, y: -ny }; });
