const petRay = new THREE.Raycaster(), petAt = new THREE.Vector2();
const onHeadAt = e => { if (!(e.target instanceof Node) || !stageEl.contains(e.target) || (e.target.closest && e.target.closest('button, input, a, .catta-reminder, .catta-rest-pill, .pk-reminder, .pk-rest-pill, .pk-focus-pill'))) return 0; const r = renderer.domElement.getBoundingClientRect(); petAt.set((e.clientX - r.left) / r.width * 2 - 1, -((e.clientY - r.top) / r.height * 2 - 1)); petRay.setFromCamera(petAt, camera);
  if (!petRay.intersectObject(head, true).length) return 0; proj.setFromMatrixPosition(head.matrixWorld).project(camera); return petAt.x > proj.x ? -1 : 1; };
